 b=p.chromium.launch(headless=True,args=['--no-sandbox']);page=b.new_page(viewport={'width':1440,'height':1200});errors=[];page.on('dialog',lambda d:d.accept());page.on('pageerror',lambda e:errors.append(str(e)))
